        /// <summary>
        /// Zero-alloc block (multi-RHS) Conjugate Gradient for an SPD A and s simultaneous right-hand
        /// sides, generic over BOTH the operator (<see cref="IfloatLinearOperator"/>) and the
        /// preconditioner (<see cref="IfloatPreconditioner"/>). A TRUE block method: it builds ONE
        /// shared Krylov subspace from all s RHS, with s x s block coefficients, streaming A over the
        /// whole block once per iteration via <c>ApplyBlock</c> -- not s independent scalar solves. All
        /// s columns share the iteration count, so they converge together in ≤ the iterations the
        /// slowest single RHS would need alone (the block-Krylov advantage).
        ///
        /// B and X are s ROWS x n COLS (row j = the j-th RHS / solution, length n = A.Rows); X is
        /// warm-startable. R, P, Q, Z are s x n block scratch (Z UNUSED under the identity
        /// preconditioner -- pass <c>default</c>). Convergence is per column against tol²·‖B[j]‖²; a
        /// rank-deficient RHS block (linearly dependent columns) is handled by a ridge-regularized s x s
        /// solve rather than breaking down. Returns a <see cref="BlockSolveInfo"/>.
        /// </summary>
        public static BlockSolveInfo bcg<TOp, TPre>(in TOp A, in TPre M, in floatMxN B, ref floatMxN X,
                                        ref floatMxN R, ref floatMxN P, ref floatMxN Q, ref floatMxN Z,
                                        int maxIter, float tol)
            where TOp : struct, IfloatLinearOperator
            where TPre : struct, IfloatPreconditioner
        {
            if (A.Rows != A.Cols) throw new ArgumentException("bcg (block): A must be square");
            int n = A.Rows;
            int s = B.M_Rows;
            if (B.N_Cols != n) throw new ArgumentException("bcg (block): B must be s x A.Rows");
            if (X.M_Rows != s || X.N_Cols != n) throw new ArgumentException("bcg (block): X must match B");
            if (R.M_Rows != s || R.N_Cols != n) throw new ArgumentException("bcg (block): R must match B");
            if (P.M_Rows != s || P.N_Cols != n) throw new ArgumentException("bcg (block): P must match B");
            if (Q.M_Rows != s || Q.N_Cols != n) throw new ArgumentException("bcg (block): Q must match B");
            if (!M.IsIdentity && (Z.M_Rows != s || Z.N_Cols != n))
                throw new ArgumentException("bcg (block): Z must match B");
            if (maxIter < 1) throw new ArgumentException("bcg (block): maxIter must be >= 1");

            unsafe
            {
                int cnt = M.IsIdentity ? 5 : 6;
                long* ptrs = stackalloc long[6];
                ptrs[0] = (long)X.Data.Ptr; ptrs[1] = (long)R.Data.Ptr; ptrs[2] = (long)P.Data.Ptr;
                ptrs[3] = (long)Q.Data.Ptr; ptrs[4] = (long)B.Data.Ptr;
                if (!M.IsIdentity) ptrs[5] = (long)Z.Data.Ptr;
                RequireDistinctBuffers("bcg (block): X/R/P/Q/Z/B must be distinct", ptrs, cnt);
            }

            // s x s coefficient scratch + per-column thresholds + row scratch for the preconditioner.
            var PQ    = new floatMxN(s, s, Allocator.Temp, true);
            var RZ    = new floatMxN(s, s, Allocator.Temp, true);
            var RZnew = new floatMxN(s, s, Allocator.Temp, true);
            var coef  = new floatMxN(s, s, Allocator.Temp, true);
            var work  = new floatMxN(s, s, Allocator.Temp, true);
            var T     = new floatMxN(s, n, Allocator.Temp, true);   // s x n GEMM target for block updates
            var thr   = new floatN(s);
            floatN rowIn = default, rowOut = default;
            if (!M.IsIdentity) { rowIn = new floatN(n); rowOut = new floatN(n); }

            IterativeSolveStatus status = IterativeSolveStatus.MaxIterations;
            int iters = maxIter;
            int converged = 0;
            double maxr = 0;

            // Per-column thresholds tol^2 ||B[j]||^2.
            BuildColumnThresholdsPlain(in B, ref thr, s, n, tol);

            // R = B - A X.
            BlockResidual(in A, in X, in B, ref Q, ref R, s, n);

            converged = CountConverged(in R, in thr, s, n, out maxr);
            if (converged == s) { status = IterativeSolveStatus.Converged; iters = 0; goto cleanup; }

            // Z = M^-1 R (identity: Z == R, used directly); P = Z; RZ = R^T Z.
            if (M.IsIdentity)
            {
                CopyBlock(in R, ref P, s, n);
                BlockGram(in R, in R, ref RZ, s);
            }
            else
            {
                BlockApplyPre(in M, in R, ref Z, s, n, ref rowIn, ref rowOut);
                CopyBlock(in Z, ref P, s, n);
                BlockGram(in R, in Z, ref RZ, s);
            }

            for (int k = 0; k < maxIter; k++)
            {
                A.ApplyBlock(in P, ref Q, s);             // Q = A P
                BlockGram(in P, in Q, ref PQ, s);         // PQ = P^T A P (s x s SPD)

                // alpha = (P^T A P)^-1 (R^T Z);   coef <- RZ, solved in place.
                CopyMat(in RZ, ref coef, s);
                if (!BlockSolveSPD(in PQ, ref coef, ref work, s))
                { status = IterativeSolveStatus.Breakdown; iters = k; goto cleanup; }

                BlockCTV(in coef, in P, ref T); BlockAdd(ref X, in T, (float)1);    // X += alpha^T P
                BlockCTV(in coef, in Q, ref T); BlockAdd(ref R, in T, (float)(-1)); // R -= alpha^T Q

                converged = CountConverged(in R, in thr, s, n, out maxr);
                if (converged == s)
                {
                    // Verify-at-exit: the recurrence residual can drift from the true B - A X on an
                    // ill-conditioned SPD A. Q is idle here (last read by the BlockCTV two lines up,
                    // next write is next iteration's A P or this iteration's beta-step BlockCTV) --
                    // reuse it for a fresh A X and only trust Converged if that also clears thr.
                    BlockResidual(in A, in X, in B, ref Q, s, n);
                    int freshConverged = CountConverged(in Q, in thr, s, n, out double freshMaxr);
                    if (freshConverged == s)
                    {
                        converged = freshConverged; maxr = freshMaxr;
                        status = IterativeSolveStatus.Converged; iters = k + 1; goto cleanup;
                    }
                }

                // Z = M^-1 R ; RZnew = R^T Z.
                if (M.IsIdentity)
                    BlockGram(in R, in R, ref RZnew, s);
                else
                {
                    BlockApplyPre(in M, in R, ref Z, s, n, ref rowIn, ref rowOut);
                    BlockGram(in R, in Z, ref RZnew, s);
                }

                // beta = (R^T Z)^-1 (R_new^T Z_new);   coef <- RZnew, solved in place.
                CopyMat(in RZnew, ref coef, s);
                if (!BlockSolveSPD(in RZ, ref coef, ref work, s))
                { status = IterativeSolveStatus.Breakdown; iters = k + 1; goto cleanup; }

                // P = Zeff + beta^T P: stage beta^T P into Q (free now), then P = Zeff + Q.
                BlockCTV(in coef, in P, ref Q);
                if (M.IsIdentity) BlockZplusT(in R, in Q, ref P);
                else              BlockZplusT(in Z, in Q, ref P);

                CopyMat(in RZnew, ref RZ, s);
            }

        cleanup:
            PQ.Dispose(); RZ.Dispose(); RZnew.Dispose(); coef.Dispose(); work.Dispose(); T.Dispose(); thr.Dispose();
            if (!M.IsIdentity) { rowIn.Dispose(); rowOut.Dispose(); }
            // Ridge version keeps the full block width every iteration (no column dropping) -> minActive = s.
            return new BlockSolveInfo { rhs = s, converged = converged, iterations = iters, maxRnorm = maxr, minActive = s, status = status };
        }

